\[
\mathcal M(d,q)
=
\left\{
P:
|\operatorname{supp}_P(X)|\le d,\;
P\text{ satisfies }
\cref{obj:ass:randomized-independence,obj:ass:balanced-randomization,obj:ass:consistency,obj:ass:mar,obj:ass:arrival-floor}
\right\}.
\]
Here \(d\) is a positive integer, \(q\in[1/2,1]\) is the known cellwise arrival floor, and \(\operatorname{supp}_P(X)\) is the set of baseline labels with positive probability under \(P\).

\[
\mathfrak R^*_{n,d,q}
=
\inf_{T\in\mathcal T_n}
\sup_{P\in\mathcal M(d,q)}
\mathbb E_P
\left[
\left\{
T(O_1,\ldots,O_n)-\tau(P)
\right\}^2
\right].
\]

\[
\mathfrak L^*_{n,d,q,\alpha}
=
\inf_{I\in\mathcal C_\alpha(n,d,q)}
\sup_{P\in\mathcal M(d,q)}
\mathbb E_P
\left[
\operatorname{length}\{I(O^n)\}
\right].
\]
For \(I(O^n)=[L,U]\), its length is \(U-L\).

\[
r_{n,d,q}
=
\frac{1}{n}
+
(1-q)^2
\min\left\{
1,
\left[\frac{d}{n\log(e+n)}\right]^2
\right\}
=
\frac{1}{n}+g_{n,d,q}^2.
\]

For each fixed noncoverage level \(\alpha\in(0,1/2)\), there exist constants \(0<c_\alpha<C_\alpha<\infty\), depending only on \(\alpha\), such that, for every pair of positive integers \(n,d\) and every \(q\in[1/2,1]\), the minimax expected interval length \(\mathfrak L^*_{n,d,q,\alpha}\) from \cref{obj:def:length-risk} and the squared-error benchmark \(r_{n,d,q}\) from \cref{obj:def:rate} satisfy
\[
c_\alpha\sqrt{r_{n,d,q}}
\le \mathfrak L^*_{n,d,q,\alpha}
\le C_\alpha\sqrt{r_{n,d,q}}.
\]

There exists a universal numerical constant \(0<C_U<\infty\) such that, for every choice satisfying
\begin{itemize}
\item \textbf{(Sample size and dimension.)} \(n,d\) are integers with \(n\ge1\) and \(d\ge1\);
\item \textbf{(Arrival floor.)} \(q\in[1/2,1]\);
\item \textbf{(Law and sampling.)} \(P\in\mathcal M(d,q)\), and \(O_1,\ldots,O_n\) are independent observed records with common law \(P_O\), the observed-law image of \(P\);
\end{itemize}
the estimator \(\widehat\tau_{\mathrm{MM}}\) satisfies
\[
\mathbb E_P\!\left[
  \bigl(\widehat\tau_{\mathrm{MM}}-\tau(P)\bigr)^2
\right]
\le C_U r_{n,d,q},
\]
where the expectation is over the stated independent sample.

4f96504becbfe91d.statement:
/-- A supplied sample law equals the iid observed-data product law. Given [the specified input `d`](hyp:d), [the specified input `P`](hyp:P), [the specified input `n`](hyp:n), [the stated mathematical conclusion holds](goal). Given [the specified input `μ`](hyp:μ). -/
def IidSample {d : ℕ} (P : FullLaw d) (n : ℕ) (μ : Measure (Fin n → Obs d)) : Prop :=
  μ = samplePi P n

33ea8ee2fb7c85fd.statement:
/-- Balanced Bernoulli treatment allocation. Given [the specified input `P`](hyp:P), [the stated mathematical conclusion holds](goal). -/
def BalancedRandomization (P : FullLaw d) : Prop :=
  armMass P true = (1 : ℝ) / 2

e8d6e65d7446e1ab.statement:
/-- Uniform arrival floor on occupied cells. Given [the specified input `q`](hyp:q), [the specified input `P`](hyp:P), [the stated mathematical conclusion holds](goal). -/
def ArrivalFloor (q : ℝ) (P : FullLaw d) : Prop :=
  ∀ x a s, 0 < cellMass P x a s → q ≤ arrivalProb P x a s

9dd748143885d66d.statement:
/-- Honest connected confidence intervals at noncoverage level `α`. Given [the specified input `n`](hyp:n), [the specified input `d`](hyp:d), [the specified input `q`](hyp:q), [the stated mathematical conclusion holds](goal). Given [the specified input `α`](hyp:α). -/
def HonestIntervalClass (n d : ℕ) (q α : ℝ) :=
  {I : IntervalProc n d // Honest n d q α I}

de686f199b17efde.statement:
  -- @realizes M_dq(laws satisfying randomization, consistency, MAR, arrival floor)

/-- A law with its certificate of membership in the MAR class. -/
abbrev ClassLaw (d : ℕ) (q : ℝ) := {P : FullLaw d // LawClass d q P}

d90bdd506454671f.statement:
/-- Uniform coverage over the legal law class. -/
def Honest (n d : ℕ) (q α : ℝ) (I : IntervalProc n d) : Prop :=
  ∀ P : ClassLaw d q,
    1 - α ≤ (samplePi P.val n).real
      {o | tau P.val ∈ Set.Icc (I.lo o) (I.hi o)}
